if('scrollRestoration' in history){history.scrollRestoration='manual';}document.addEventListener('DOMContentLoaded',()=>{document.body.addEventListener('click',async(e)=>{const link=e.target.closest('a');if(!link)return;const href=link.getAttribute('href');if(!href||href==='#'||href.startsWith('javascript:')||href.startsWith('mailto:')||href.startsWith('tel:')){if(href==='#')e.preventDefault();return;}if(link.target==='_blank'||link.hasAttribute('data-no-spa')||e.ctrlKey||e.metaKey||e.shiftKey)return;const targetUrl=new URL(link.href,window.location.href);const currentUrl=new URL(window.location.href);if(targetUrl.origin!==currentUrl.origin)return;if(targetUrl.pathname===currentUrl.pathname&&targetUrl.hash!==''){e.preventDefault();const targetId=targetUrl.hash.substring(1);const targetElement=document.getElementById(targetId);if(targetElement){targetElement.scrollIntoView({behavior:'smooth'});window.history.pushState(null,null,targetUrl.hash);}return;}e.preventDefault();await navigateTo(targetUrl.href);});window.addEventListener('popstate',async(e)=>{await navigateTo(window.location.href,false);});});async function navigateTo(url,pushState=true){document.dispatchEvent(new CustomEvent('stardust:navigating'));try {const response=await fetch(url);if(!response.ok)throw new Error(`HTTP error!status:${response.status}`);const htmlString=await response.text();const parser=new DOMParser();const doc=parser.parseFromString(htmlString,'text/html');const newTitle=doc.querySelector('title')?.innerText;const layoutTarget=doc.querySelector('#stardust-app');if(layoutTarget){let nextClass=doc.body.className||'theme-oceanview';let activeTheme='auto';try {const stored=localStorage.getItem('reader-settings');if(stored){const settings=JSON.parse(stored);if(settings&&settings.theme){activeTheme=settings.theme;}}}catch(e){}nextClass=nextClass .replace(/\btheme-(auto|light|sepia|dark|dark-sepia|sepia-system|custom)\b/g,'').trim()+' theme-'+activeTheme;document.body.className=nextClass.trim();delete document.body.dataset.narrativeTheme;document.documentElement.style.colorScheme=(activeTheme==='light'||activeTheme==='sepia')?'light':((activeTheme==='dark'||activeTheme==='dark-sepia')?'dark':'light dark');document.head.querySelectorAll('meta[name="stardust-narrative-theme"],link#narrative-theme-css').forEach(el=>el.remove());const currentApp=document.querySelector('#stardust-app');if(currentApp){currentApp.replaceWith(layoutTarget);}const newlyInjectedApp=document.querySelector('#stardust-app');const scripts=newlyInjectedApp.querySelectorAll('script');scripts.forEach(oldScript=>{const newScript=document.createElement('script');Array.from(oldScript.attributes).forEach(attr=>newScript.setAttribute(attr.name,attr.value));newScript.appendChild(document.createTextNode(oldScript.innerHTML));oldScript.parentNode.replaceChild(newScript,oldScript);});const newLinks=doc.head.querySelectorAll('link[rel="stylesheet"]');const currentLinks=Array.from(document.head.querySelectorAll('link[rel="stylesheet"]')).map(l=>l.href);newLinks.forEach(newLink=>{if(!currentLinks.includes(newLink.href)){const clonedLink=newLink.cloneNode();document.head.appendChild(clonedLink);}});if(newTitle)document.title=newTitle;if(pushState)window.history.pushState({url:url},newTitle,url);window.scrollTo({top:0,left:0,behavior:'instant'});const readingPane=document.getElementById('stardust-reading-pane');if(readingPane){readingPane.setAttribute('tabindex','-1');readingPane.focus({preventScroll:true});}document.dispatchEvent(new CustomEvent('stardust:loaded'));}else {window.location.href=url;}}catch(error){console.error('Stardust SPA Error:',error);window.location.href=url;}}
